-- >>> supabase/migrations/0001_core_schema.sql
-- =============================================================================
-- 0001_core_schema.sql — Waskey IPM Phase 0 core schema
--
-- Template/instance model with structured-flexible specs (JSONB), append-only
-- ledgers for raw materials and QC, and revision pinning so the as-poured truth
-- survives later design changes.
--
-- Conventions: snake_case, plural tables, PK `id uuid`. `<singular>_id` only for
-- real foreign keys. Closed sets use a domain noun / `_type` with a CHECK, never
-- `_id`. All UUIDs are client-generatable (default gen_random_uuid() server-side).
-- =============================================================================

-- gen_random_uuid() lives in pgcrypto (preinstalled on Supabase; safe to ensure).
create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- Shared: updated_at trigger (DRY — one function, reused on every mutable table)
-- -----------------------------------------------------------------------------
create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- =============================================================================
-- PROJECTS
-- =============================================================================
create table projects (
  id          uuid primary key default gen_random_uuid(),
  job_number  text not null,
  name        text not null,
  client      text,
  location    text,
  status      text not null default 'active'
                check (status in ('active', 'closed', 'on_hold')),
  is_stock    boolean not null default false,   -- synthetic make-to-stock project
  created_at  timestamptz not null default now()
);
create unique index uq_projects_job_number on projects (job_number);

-- =============================================================================
-- PRODUCT DESIGNS  (the 60-year drawing catalog = reusable templates)
--   spec_template declares a family's fields/types/units/validation/QC gates.
-- =============================================================================
create table product_designs (
  id                  uuid primary key default gen_random_uuid(),
  drawing_no          text not null,
  family              text not null,            -- e.g. "Platform Deck Panel"
  name                text not null,
  base_specs          jsonb not null default '{}'::jsonb,
  spec_template       jsonb not null default '{}'::jsonb,
  default_components   jsonb not null default '[]'::jsonb,
  revision            integer not null default 1 check (revision >= 1),
  superseded_by_id    uuid references product_designs (id),
  created_at          timestamptz not null default now()
);
create unique index uq_product_designs_drawing_rev
  on product_designs (drawing_no, revision);
create index idx_product_designs_family on product_designs (family);

-- =============================================================================
-- MIX DESIGNS  (concrete recipe: both a spec and a bill of materials)
-- =============================================================================
create table mix_designs (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  target_psi  integer check (target_psi > 0),
  slump_in    numeric(5, 2) check (slump_in >= 0),
  recipe      jsonb not null default '[]'::jsonb,  -- [{material_id, qty, unit}] per cu yd
  created_at  timestamptz not null default now()
);
create unique index uq_mix_designs_name on mix_designs (name);

-- =============================================================================
-- CATEGORIES  (Rebar, Embeds, Admixture, Cement, ...)
-- =============================================================================
create table categories (
  id    uuid primary key default gen_random_uuid(),
  name  text not null
);
create unique index uq_categories_name on categories (name);

-- =============================================================================
-- SPEC ATTRIBUTES  (field definitions owned by a product_design family OR a
--   material category). Spec *values* live as JSONB on the instance.
-- =============================================================================
create table spec_attributes (
  id           uuid primary key default gen_random_uuid(),
  owner_type   text not null check (owner_type in ('category', 'product_design')),
  owner_id     uuid not null,            -- polymorphic; validated in-app per owner_type
  name         text not null,
  value_type   text not null
                 check (value_type in ('number', 'text', 'enum', 'bool', 'ref', 'list')),
  unit         text,                     -- "ft" | "in" | "psi" | "lb" | ... (nullable)
  required     boolean not null default false,
  qc_gate      boolean not null default false,
  valid_min    numeric,
  valid_max    numeric,
  enum_values   jsonb,                    -- for value_type = 'enum'
  created_at   timestamptz not null default now()
);
create index idx_spec_attributes_owner on spec_attributes (owner_type, owner_id);
create unique index uq_spec_attributes_owner_name
  on spec_attributes (owner_type, owner_id, name);

-- =============================================================================
-- MATERIALS  (raw-material catalog; spec_values JSONB per its category template)
-- =============================================================================
create table materials (
  id            uuid primary key default gen_random_uuid(),
  category_id   uuid not null references categories (id),
  description   text not null,
  default_uom   text not null,           -- unit of measure: lb, ea, ft, cu_yd, ...
  default_cost  numeric(12, 4) check (default_cost >= 0),
  spec_values   jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now()
);
create index idx_materials_category on materials (category_id);

-- =============================================================================
-- FORMS  (reusable molds; wear tracked via use_count)
-- =============================================================================
create table forms (
  id                  uuid primary key default gen_random_uuid(),
  name                text not null,
  product_design_id   uuid references product_designs (id),
  location            text,
  condition           text not null default 'good'
                        check (condition in ('good', 'worn', 'needs_repair', 'retired')),
  use_count           integer not null default 0 check (use_count >= 0),
  current_cast_run_id uuid,              -- FK added after cast_runs exists (below)
  created_at          timestamptz not null default now()
);
create unique index uq_forms_name on forms (name);

-- =============================================================================
-- CAST RUNS  (one pour: consumes materials per a mix, in a form, yields pieces.
--   Snapshots the design revision actually poured — pins the as-poured truth.)
-- =============================================================================
create table cast_runs (
  id                       uuid primary key default gen_random_uuid(),
  cast_date                date not null default current_date,
  product_design_id        uuid not null references product_designs (id),
  product_design_revision  integer not null check (product_design_revision >= 1),
  mix_design_id            uuid references mix_designs (id),
  form_id                  uuid references forms (id),
  batch_no                 text not null,
  qty                      integer not null default 1 check (qty >= 1),
  labor_hours              numeric(8, 2) check (labor_hours >= 0),
  created_at               timestamptz not null default now()
);
create index idx_cast_runs_design on cast_runs (product_design_id);
create index idx_cast_runs_batch_no on cast_runs (batch_no);

-- Deferred FK: forms.current_cast_run_id -> cast_runs.id (circular dependency).
alter table forms
  add constraint fk_forms_current_cast_run
  foreign key (current_cast_run_id) references cast_runs (id);

-- =============================================================================
-- PIECES  (serialized instances — the heart of the system. NEVER a SKU.)
--   spec_values + as_built_components are per-piece JSONB; revision pins the
--   design version actually cast.
-- =============================================================================
create table pieces (
  id                       uuid primary key default gen_random_uuid(),
  mark_no                  text not null,
  project_id               uuid references projects (id),
  product_design_id        uuid not null references product_designs (id),
  product_design_revision  integer not null check (product_design_revision >= 1),
  cast_run_id              uuid references cast_runs (id),
  spec_values              jsonb not null default '{}'::jsonb,
  as_built_components      jsonb not null default '[]'::jsonb,
  weight_lb                numeric(12, 2) check (weight_lb >= 0),
  status                   text not null default 'in_production'
                             check (status in (
                               'in_production', 'curing', 'qc',
                               'ready', 'staged', 'delivered'
                             )),
  yard_location            text,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);
create unique index uq_pieces_mark_no on pieces (mark_no);
create index idx_pieces_project on pieces (project_id);
create index idx_pieces_status on pieces (status);
create index idx_pieces_yard_location on pieces (yard_location);
create index idx_pieces_cast_run on pieces (cast_run_id);

create trigger trg_pieces_updated_at
  before update on pieces
  for each row execute function set_updated_at();

-- =============================================================================
-- QC TESTS  (APPEND ONLY — bound to the piece/batch revision actually poured)
-- =============================================================================
create table qc_tests (
  id          uuid primary key default gen_random_uuid(),
  piece_id    uuid references pieces (id),
  batch_no    text,                       -- batch-level tests (cylinders) may not pin a piece
  test_type   text not null
                check (test_type in (
                  'break_7day', 'break_28day', 'water_test', 'other'
                )),
  value       numeric,
  unit        text,
  pass        boolean,
  tested_at   timestamptz not null default now(),
  tested_by   text,
  -- At least one of piece_id / batch_no must identify what was tested.
  constraint chk_qc_tests_target check (piece_id is not null or batch_no is not null)
);
create index idx_qc_tests_piece on qc_tests (piece_id);
create index idx_qc_tests_batch_no on qc_tests (batch_no);

-- =============================================================================
-- INVENTORY TXN  (APPEND ONLY ledger — on-hand is summed from this, never stored)
-- =============================================================================
create table inventory_txns (
  id            uuid primary key default gen_random_uuid(),
  txn_type      text not null
                  check (txn_type in ('receipt', 'issue_to_cast_run', 'transfer', 'adjust')),
  material_id   uuid not null references materials (id),
  qty           numeric(14, 4) not null,    -- signed by convention per txn_type (app-enforced)
  unit_cost     numeric(12, 4) check (unit_cost >= 0),
  from_location text,
  to_location   text,
  cast_run_id   uuid references cast_runs (id),
  project_id    uuid references projects (id),
  user_id       uuid,                       -- the actor; from auth.uid() on the client
  created_at    timestamptz not null default now()
);
create index idx_inventory_txns_material on inventory_txns (material_id);
create index idx_inventory_txns_cast_run on inventory_txns (cast_run_id);
create index idx_inventory_txns_project on inventory_txns (project_id);
create index idx_inventory_txns_type on inventory_txns (txn_type);

-- =============================================================================
-- Notes
--  * Balances (material on-hand), job material cost, and "pieces available" are
--    DERIVED by summing inventory_txns / filtering pieces — never stored as
--    mutable columns. See data-model.md §4.
--  * Spec validation (required fields, ranges, qc_gate enforcement before status
--    advances past 'qc') runs in-app for v1, not as DB CHECK constraints — easier
--    to iterate; hot rules can move into the DB later.
-- =============================================================================

-- >>> supabase/migrations/0002_rls_policies.sql
-- =============================================================================
-- 0002_rls_policies.sql — Row-level security + append-only enforcement
--
-- Single-tenant model: any authenticated Waskey user may read/write the
-- operational tables. The append-only ledgers (inventory_txns, qc_tests) grant
-- INSERT + SELECT only — no UPDATE/DELETE — so corrections are new rows and the
-- audit trail can never drift. This is the DB-side guarantee behind the
-- traceability clients pay for.
--
-- Targets Supabase: references the `authenticated` role and auth.uid(). On a
-- plain Postgres without the Supabase auth schema, this file will error on those
-- references — apply 0001 + seed there, and this file against a Supabase target.
-- =============================================================================

-- Enable RLS on every table. With RLS on and no permissive policy, access is
-- denied by default — so each table below gets explicit policies.
alter table projects         enable row level security;
alter table product_designs  enable row level security;
alter table mix_designs      enable row level security;
alter table categories       enable row level security;
alter table spec_attributes  enable row level security;
alter table materials        enable row level security;
alter table forms            enable row level security;
alter table cast_runs        enable row level security;
alter table pieces           enable row level security;
alter table qc_tests         enable row level security;
alter table inventory_txns   enable row level security;

-- -----------------------------------------------------------------------------
-- Full-access tables (single tenant): authenticated users get full CRUD.
-- One FOR ALL policy per table, USING + WITH CHECK = authenticated.
-- -----------------------------------------------------------------------------
do $$
declare
  tbl text;
  full_access_tables text[] := array[
    'projects', 'product_designs', 'mix_designs', 'categories',
    'spec_attributes', 'materials', 'forms', 'cast_runs', 'pieces'
  ];
begin
  foreach tbl in array full_access_tables loop
    execute format(
      'create policy %I on %I for all to authenticated using (true) with check (true)',
      tbl || '_authenticated_all', tbl
    );
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Append-only ledgers: INSERT + SELECT only. No UPDATE, no DELETE policy is
-- created, so with RLS enabled those operations are denied for all non-superuser
-- roles. Corrections are new rows (an `adjust` txn, a new qc_test), never edits.
-- -----------------------------------------------------------------------------

-- inventory_txns
create policy inventory_txns_authenticated_select
  on inventory_txns for select to authenticated using (true);
create policy inventory_txns_authenticated_insert
  on inventory_txns for insert to authenticated with check (true);

-- qc_tests
create policy qc_tests_authenticated_select
  on qc_tests for select to authenticated using (true);
create policy qc_tests_authenticated_insert
  on qc_tests for insert to authenticated with check (true);

-- =============================================================================
-- Table privileges (GRANTs)
--
-- RLS policies only take effect AFTER the role passes the table-level privilege
-- check. Tables created via raw `CREATE TABLE` (e.g. the SQL editor) grant
-- nothing to the Supabase API roles, so without these GRANTs every query fails
-- with "permission denied" before RLS even runs. Grant the API role the verbs
-- its policies allow; RLS then scopes the rows.
--
-- `authenticated` = a logged-in user (what the app uses). `anon` is intentionally
-- granted nothing here — unauthenticated clients get no access.
-- =============================================================================

-- Full-access tables: authenticated may read and write.
grant select, insert, update, delete on
  projects, product_designs, mix_designs, categories,
  spec_attributes, materials, forms, cast_runs, pieces
to authenticated;

-- Append-only ledgers: authenticated may read and insert only.
grant select, insert on inventory_txns, qc_tests to authenticated;

-- =============================================================================
-- Defense in depth: revoke UPDATE/DELETE on the ledgers from the API roles so
-- the append-only invariant holds even if a future permissive policy slips in.
-- =============================================================================
revoke update, delete on inventory_txns from authenticated, anon;
revoke update, delete on qc_tests       from authenticated, anon;

-- >>> supabase/migrations/0003_grants.sql
-- =============================================================================
-- 0003_grants.sql — table privileges for the Supabase API roles
--
-- Standalone, re-runnable. Apply this if 0002 was run BEFORE the GRANT block was
-- added to it (grants are idempotent, so running this is always safe). Without
-- these, a signed-in user's queries fail with "permission denied" because RLS
-- only runs after the table-level privilege check passes.
-- =============================================================================

-- Full-access tables: authenticated may read and write.
grant select, insert, update, delete on
  projects, product_designs, mix_designs, categories,
  spec_attributes, materials, forms, cast_runs, pieces
to authenticated;

-- Append-only ledgers: authenticated may read and insert only.
grant select, insert on inventory_txns, qc_tests to authenticated;

-- Keep the append-only invariant even if a permissive policy is added later.
revoke update, delete on inventory_txns from authenticated, anon;
revoke update, delete on qc_tests       from authenticated, anon;

-- >>> supabase/migrations/0004_create_product_design_fn.sql
-- =============================================================================
-- 0004_create_product_design_fn.sql — atomic product-design creation
--
-- The spec-template definer writes a product_design AND its spec_attribute rows
-- AND mirrors the fields into product_design.spec_template (JSONB). That is a
-- multi-table write that must be all-or-nothing: a family with half its fields
-- corrupts the validation the whole system relies on. PostgREST can't span a
-- transaction across separate calls, so the write lives in this function — one
-- call, one transaction (a function body runs in a single implicit transaction).
--
-- Input: the family metadata + a JSON array of attribute definitions. Output:
-- the new product_design id.
--
-- SECURITY INVOKER (the default): the function runs as the calling user, so RLS
-- and the table grants from 0002/0003 still apply — no privilege escalation.
-- =============================================================================

create or replace function create_product_design(
  p_drawing_no    text,
  p_family        text,
  p_name          text,
  p_revision      integer,
  p_attributes    jsonb         -- array of { name, value_type, unit, required,
                                --            qc_gate, valid_min, valid_max, enum_values }
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_design_id     uuid := gen_random_uuid();
  v_template      jsonb := '{}'::jsonb;
  v_attr          jsonb;
  v_field         jsonb;
begin
  -- Build the spec_template JSONB mirror from the attribute array, and validate
  -- each attribute as we go.
  for v_attr in select * from jsonb_array_elements(coalesce(p_attributes, '[]'::jsonb))
  loop
    if coalesce(trim(v_attr->>'name'), '') = '' then
      raise exception 'Each spec attribute must have a non-empty name';
    end if;
    if coalesce(v_attr->>'value_type', '') not in
       ('number','text','enum','bool','ref','list') then
      raise exception 'Invalid value_type "%" for attribute "%"',
        v_attr->>'value_type', v_attr->>'name';
    end if;

    -- One field entry in the template mirror: { type, unit?, required, qc_gate,
    -- min?, max?, values? } — shaped like the data-model doc's example.
    v_field := jsonb_build_object(
      'type',     v_attr->>'value_type',
      'required', coalesce((v_attr->>'required')::boolean, false),
      'qc_gate',  coalesce((v_attr->>'qc_gate')::boolean, false)
    );
    if nullif(v_attr->>'unit', '') is not null then
      v_field := v_field || jsonb_build_object('unit', v_attr->>'unit');
    end if;
    if nullif(v_attr->>'valid_min', '') is not null then
      v_field := v_field || jsonb_build_object('min', (v_attr->>'valid_min')::numeric);
    end if;
    if nullif(v_attr->>'valid_max', '') is not null then
      v_field := v_field || jsonb_build_object('max', (v_attr->>'valid_max')::numeric);
    end if;
    if v_attr ? 'enum_values' and jsonb_typeof(v_attr->'enum_values') = 'array' then
      v_field := v_field || jsonb_build_object('values', v_attr->'enum_values');
    end if;

    v_template := v_template || jsonb_build_object(v_attr->>'name', v_field);
  end loop;

  -- Insert the design with its JSONB mirror.
  insert into product_designs (id, drawing_no, family, name, spec_template, revision)
  values (v_design_id, p_drawing_no, p_family, p_name, v_template, coalesce(p_revision, 1));

  -- Insert one spec_attribute row per field (the queryable source of truth).
  for v_attr in select * from jsonb_array_elements(coalesce(p_attributes, '[]'::jsonb))
  loop
    insert into spec_attributes (
      owner_type, owner_id, name, value_type, unit,
      required, qc_gate, valid_min, valid_max, enum_values
    )
    values (
      'product_design',
      v_design_id,
      v_attr->>'name',
      v_attr->>'value_type',
      nullif(v_attr->>'unit', ''),
      coalesce((v_attr->>'required')::boolean, false),
      coalesce((v_attr->>'qc_gate')::boolean, false),
      nullif(v_attr->>'valid_min', '')::numeric,
      nullif(v_attr->>'valid_max', '')::numeric,
      case when v_attr ? 'enum_values' and jsonb_typeof(v_attr->'enum_values') = 'array'
           then v_attr->'enum_values' else null end
    );
  end loop;

  return v_design_id;
end;
$$;

-- Allow logged-in users to call it (anon gets nothing).
grant execute on function create_product_design(text, text, text, integer, jsonb)
  to authenticated;

-- >>> supabase/migrations/0005_lookup_values.sql
-- =============================================================================
-- 0005_lookup_values.sql — reusable add-if-missing lookups for the editors
--
-- Repeated free-text inputs (units, field names, enum choices, …) become shared
-- vocabularies so engineers pick instead of retype, keeping values consistent
-- ("ft" not "feet"/"FT"). Each value is scoped by a `kind`. New values are added
-- inline via add_lookup_value, which is insert-if-missing (idempotent).
-- =============================================================================

create table lookup_values (
  id          uuid primary key default gen_random_uuid(),
  kind        text not null,        -- 'unit' | 'field_name' | 'enum_value' | ...
  value       text not null,
  created_at  timestamptz not null default now()
);

-- One row per (kind, value); case-sensitive on value by design (units are).
create unique index uq_lookup_values_kind_value on lookup_values (kind, value);
create index idx_lookup_values_kind on lookup_values (kind);

-- -----------------------------------------------------------------------------
-- RLS + grants (mirrors the rest of the schema: authenticated full access)
-- -----------------------------------------------------------------------------
alter table lookup_values enable row level security;

create policy lookup_values_authenticated_all
  on lookup_values for all to authenticated using (true) with check (true);

grant select, insert, update, delete on lookup_values to authenticated;

-- -----------------------------------------------------------------------------
-- add_lookup_value — insert-if-missing, returns the canonical value.
--   Trims input; ignores blanks; safe to call repeatedly (no duplicates).
-- -----------------------------------------------------------------------------
create or replace function add_lookup_value(p_kind text, p_value text)
returns text
language plpgsql
security invoker
as $$
declare
  v_value text := trim(p_value);
begin
  if coalesce(v_value, '') = '' then
    raise exception 'Lookup value cannot be empty';
  end if;
  if coalesce(trim(p_kind), '') = '' then
    raise exception 'Lookup kind cannot be empty';
  end if;

  insert into lookup_values (kind, value)
  values (trim(p_kind), v_value)
  on conflict (kind, value) do nothing;

  return v_value;
end;
$$;

grant execute on function add_lookup_value(text, text) to authenticated;

-- -----------------------------------------------------------------------------
-- Seed common values so the lists aren't empty on day one.
-- -----------------------------------------------------------------------------
insert into lookup_values (kind, value) values
  ('unit', 'ft'),
  ('unit', 'in'),
  ('unit', 'psi'),
  ('unit', 'lb'),
  ('unit', 'cu_yd'),
  ('unit', 'ea'),
  ('field_name', 'length_ft'),
  ('field_name', 'width_ft'),
  ('field_name', 'thickness_in'),
  ('field_name', 'target_psi'),
  ('field_name', 'water_test'),
  ('enum_value', 'required'),
  ('enum_value', 'n/a')
on conflict (kind, value) do nothing;

-- >>> supabase/migrations/0006_create_piece_fn.sql
-- =============================================================================
-- 0006_create_piece_fn.sql — create a piece instance from a design
--
-- The piece clone-and-edit editor saves a single piece: universal fields plus
-- its spec_values JSONB (validated in-app against the template). This is a
-- single-row insert, but it lives in a function so the server can pin the
-- as-poured design revision from the design itself (not trust the client) and
-- to keep one clean entry point for piece creation.
--
-- SECURITY INVOKER: runs as the caller, so RLS + grants still apply.
-- =============================================================================

create or replace function create_piece(
  p_mark_no            text,
  p_product_design_id  uuid,
  p_project_id         uuid,
  p_spec_values        jsonb,
  p_weight_lb          numeric,
  p_yard_location      text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_piece_id   uuid := gen_random_uuid();
  v_revision   integer;
begin
  if coalesce(trim(p_mark_no), '') = '' then
    raise exception 'Mark number is required';
  end if;

  -- Pin the design revision from the design row (server-authoritative).
  select revision into v_revision
  from product_designs
  where id = p_product_design_id;

  if v_revision is null then
    raise exception 'Unknown product_design_id %', p_product_design_id;
  end if;

  insert into pieces (
    id, mark_no, project_id, product_design_id, product_design_revision,
    spec_values, weight_lb, status, yard_location
  )
  values (
    v_piece_id,
    trim(p_mark_no),
    p_project_id,
    p_product_design_id,
    v_revision,
    coalesce(p_spec_values, '{}'::jsonb),
    p_weight_lb,
    'in_production',                 -- lifecycle starts here
    nullif(trim(p_yard_location), '')
  );

  return v_piece_id;
end;
$$;

grant execute on function
  create_piece(text, uuid, uuid, jsonb, numeric, text)
  to authenticated;

-- >>> supabase/migrations/0007_qc_and_lifecycle_fns.sql
-- =============================================================================
-- 0007_qc_and_lifecycle_fns.sql — QC capture + manual lifecycle advancement
--
-- Two RPCs:
--   record_qc_test       — append-only insert into qc_tests (one clean entry point)
--   advance_piece_status — manual, one legal forward step at a time, with the QC
--                          gate enforced server-side when leaving 'qc'.
--
-- QC gate (to advance out of 'qc'): the piece must have
--   (a) at least one PASSING qc_test, AND
--   (b) every qc_gate spec field its design declares present (non-null) in the
--       piece's spec_values.
-- Enforcing this in the DB (not just the UI) means the invariant can't be
-- bypassed and both clients get it for free.
--
-- SECURITY INVOKER: runs as the caller, so RLS + grants still apply.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- record_qc_test — append-only QC test insert. Returns the new test id.
-- -----------------------------------------------------------------------------
create or replace function record_qc_test(
  p_piece_id   uuid,
  p_test_type  text,
  p_value      numeric,
  p_unit       text,
  p_pass       boolean,
  p_tested_by  text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_test_id uuid := gen_random_uuid();
begin
  if p_piece_id is null then
    raise exception 'piece_id is required';
  end if;
  if not exists (select 1 from pieces where id = p_piece_id) then
    raise exception 'Unknown piece_id %', p_piece_id;
  end if;
  if coalesce(p_test_type, '') not in ('break_7day','break_28day','water_test','other') then
    raise exception 'Invalid test_type "%"', p_test_type;
  end if;

  insert into qc_tests (id, piece_id, test_type, value, unit, pass, tested_by)
  values (v_test_id, p_piece_id, p_test_type, p_value, nullif(trim(p_unit), ''),
          p_pass, nullif(trim(p_tested_by), ''));

  return v_test_id;
end;
$$;

grant execute on function
  record_qc_test(uuid, text, numeric, text, boolean, text)
  to authenticated;

-- -----------------------------------------------------------------------------
-- Lifecycle order helper — index of a status in the forward sequence.
-- -----------------------------------------------------------------------------
create or replace function piece_status_rank(p_status text)
returns integer
language sql
immutable
as $$
  select case p_status
    when 'in_production' then 0
    when 'curing'        then 1
    when 'qc'            then 2
    when 'ready'         then 3
    when 'staged'        then 4
    when 'delivered'     then 5
    else -1
  end;
$$;

-- -----------------------------------------------------------------------------
-- advance_piece_status — move a piece exactly one legal step forward.
--   Rejects skips and backward moves. Enforces the QC gate when leaving 'qc'.
--   Returns the new status.
-- -----------------------------------------------------------------------------
create or replace function advance_piece_status(
  p_piece_id      uuid,
  p_target_status text
)
returns text
language plpgsql
security invoker
as $$
declare
  v_current        text;
  v_design_id      uuid;
  v_current_rank   integer;
  v_target_rank    integer;
  v_passing_tests  integer;
  v_unmet_gate     text;
begin
  select status, product_design_id
    into v_current, v_design_id
  from pieces
  where id = p_piece_id;

  if v_current is null then
    raise exception 'Unknown piece_id %', p_piece_id;
  end if;

  v_current_rank := piece_status_rank(v_current);
  v_target_rank  := piece_status_rank(p_target_status);

  if v_target_rank < 0 then
    raise exception 'Invalid target status "%"', p_target_status;
  end if;

  -- Exactly one step forward (no skipping, no going back).
  if v_target_rank <> v_current_rank + 1 then
    raise exception 'Cannot move from "%" to "%": only one step forward is allowed',
      v_current, p_target_status;
  end if;

  -- QC gate: enforced when leaving 'qc' (i.e. qc -> ready).
  if v_current = 'qc' then
    -- (a) at least one passing QC test
    select count(*) into v_passing_tests
    from qc_tests
    where piece_id = p_piece_id and pass is true;

    if v_passing_tests = 0 then
      raise exception 'QC gate: at least one passing QC test is required before "ready"';
    end if;

    -- (b) every qc_gate spec field its design declares is present (non-null)
    --     in the piece's spec_values.
    select sa.name into v_unmet_gate
    from spec_attributes sa
    join pieces p on p.id = p_piece_id
    where sa.owner_type = 'product_design'
      and sa.owner_id = v_design_id
      and sa.qc_gate is true
      and (
        not (p.spec_values ? sa.name)
        or p.spec_values -> sa.name = 'null'::jsonb
      )
    limit 1;

    if v_unmet_gate is not null then
      raise exception 'QC gate: spec field "%" must be set before "ready"', v_unmet_gate;
    end if;
  end if;

  update pieces
    set status = p_target_status
  where id = p_piece_id;

  return p_target_status;
end;
$$;

grant execute on function
  advance_piece_status(uuid, text)
  to authenticated;

-- >>> supabase/migrations/0008_convert_to_retail.sql
-- =============================================================================
-- 0008_convert_to_retail.sql — CastLedger (precast) → AceStock (tennis retail)
--
-- Repurposes the project from a custom-manufacturing traceability system into a
-- general retail inventory manager for a tennis shop, with light POS.
--
-- This is a CLEAN CUTOVER on the existing Supabase project: it drops the
-- manufacturing schema (migrations 0001–0007's domain tables/functions) and
-- builds the retail schema. It KEEPS lookup_values + add_lookup_value (reused for
-- brands, colors, etc.). Migrations 0001–0007 remain in history but are
-- superseded by this file.
--
-- Retail model:
--   category          product type (Rackets, Strings, Apparel…), owns attributes
--   attribute_defs    per-category field defs; is_variant_dimension marks the
--                     attributes whose values split a product into stock variants
--   product           a sellable model: category + brand + attributes + pricing
--   variant           a stockable SKU of a product (its variant-dimension values)
--   inventory_txns    append-only stock movements (receive/adjust/sell/transfer);
--                     on-hand per variant = sum of qty
--   sales / sale_lines light POS; recording a sale posts a sell txn per line
-- =============================================================================

create extension if not exists pgcrypto;

-- =============================================================================
-- 1. DROP the manufacturing schema (order respects FK dependencies)
-- =============================================================================
drop function if exists advance_piece_status(uuid, text) cascade;
drop function if exists record_qc_test(uuid, text, numeric, text, boolean, text) cascade;
drop function if exists piece_status_rank(text) cascade;
drop function if exists create_piece(text, uuid, uuid, jsonb, numeric, text) cascade;
drop function if exists create_product_design(text, text, text, integer, jsonb) cascade;

drop table if exists qc_tests cascade;
drop table if exists inventory_txns cascade;      -- replaced by retail version below
drop table if exists pieces cascade;
drop table if exists cast_runs cascade;
drop table if exists forms cascade;
drop table if exists spec_attributes cascade;     -- replaced by attribute_defs
drop table if exists materials cascade;
drop table if exists mix_designs cascade;
drop table if exists product_designs cascade;
drop table if exists categories cascade;          -- replaced by retail categories
drop table if exists projects cascade;
drop table if exists delivery_piece cascade;
drop table if exists delivery cascade;

-- KEPT: lookup_values + add_lookup_value (reused for brands, colors, materials…).
-- Clear precast-specific lookup rows so the lists start clean for retail.
delete from lookup_values where kind in ('unit', 'field_name', 'enum_value');

-- Shared updated_at trigger fn (recreate; old tables that used it are gone).
create or replace function set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- =============================================================================
-- 2. RETAIL SCHEMA
-- =============================================================================

-- Product categories (product types). Each owns an attribute schema.
create table categories (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now()
);
create unique index uq_categories_name on categories (name);

-- Attribute definitions per category. is_variant_dimension marks the attributes
-- whose values distinguish stock-tracked variants (e.g. grip_size, size, color).
create table attribute_defs (
  id                   uuid primary key default gen_random_uuid(),
  category_id          uuid not null references categories (id) on delete cascade,
  name                 text not null,
  value_type           text not null
                         check (value_type in ('number', 'text', 'enum', 'bool')),
  unit                 text,
  required             boolean not null default false,
  is_variant_dimension boolean not null default false,
  enum_values          jsonb,          -- for value_type = 'enum'
  sort_order           integer not null default 0,
  created_at           timestamptz not null default now()
);
create index idx_attribute_defs_category on attribute_defs (category_id);
create unique index uq_attribute_defs_cat_name on attribute_defs (category_id, name);

-- Products (sellable models). Descriptive (non-variant) attribute values live in
-- attributes JSONB; variant-defining values live on each variant.
create table products (
  id             uuid primary key default gen_random_uuid(),
  category_id    uuid not null references categories (id),
  brand          text,
  name           text not null,
  description    text,
  attributes     jsonb not null default '{}'::jsonb,
  sell_price     numeric(12, 2) check (sell_price >= 0),
  cost           numeric(12, 2) check (cost >= 0),
  reorder_point  integer check (reorder_point >= 0),
  sku            text,
  barcode        text,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index idx_products_category on products (category_id);
create index idx_products_brand on products (brand);
create unique index uq_products_sku on products (sku) where sku is not null;

create trigger trg_products_updated_at
  before update on products
  for each row execute function set_updated_at();

-- Variants: the stockable SKUs. variant_values holds the variant-dimension
-- attribute values, e.g. {"grip_size":"4 3/8"} or {"size":"10","color":"White"}.
-- A product with no variant dimensions gets exactly one "default" variant.
create table variants (
  id             uuid primary key default gen_random_uuid(),
  product_id     uuid not null references products (id) on delete cascade,
  variant_values jsonb not null default '{}'::jsonb,
  sku            text,
  barcode        text,
  sell_price     numeric(12, 2) check (sell_price >= 0),   -- overrides product price if set
  cost           numeric(12, 2) check (cost >= 0),
  reorder_point  integer check (reorder_point >= 0),
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index idx_variants_product on variants (product_id);
create unique index uq_variants_sku on variants (sku) where sku is not null;

create trigger trg_variants_updated_at
  before update on variants
  for each row execute function set_updated_at();

-- Append-only stock ledger. On-hand for a variant = sum(qty). Sign convention:
-- receipts/positive adjustments are +qty; sells/negative adjustments are -qty
-- (enforced by the app / RPCs).
create table inventory_txns (
  id            uuid primary key default gen_random_uuid(),
  txn_type      text not null
                  check (txn_type in ('receive', 'adjust', 'sell', 'transfer')),
  variant_id    uuid not null references variants (id),
  qty           numeric(14, 3) not null,        -- signed
  unit_cost     numeric(12, 2) check (unit_cost >= 0),
  location      text,
  sale_id       uuid,                            -- set for 'sell' txns (FK added below)
  note          text,
  user_id       uuid,
  created_at    timestamptz not null default now()
);
create index idx_inventory_txns_variant on inventory_txns (variant_id);
create index idx_inventory_txns_type on inventory_txns (txn_type);
create index idx_inventory_txns_sale on inventory_txns (sale_id);

-- Sales (light POS). A sale has lines; recording it posts a sell txn per line.
create table sales (
  id          uuid primary key default gen_random_uuid(),
  sold_at     timestamptz not null default now(),
  subtotal    numeric(12, 2) not null default 0 check (subtotal >= 0),
  note        text,
  user_id     uuid,
  created_at  timestamptz not null default now()
);

create table sale_lines (
  id          uuid primary key default gen_random_uuid(),
  sale_id     uuid not null references sales (id) on delete cascade,
  variant_id  uuid not null references variants (id),
  qty         integer not null check (qty > 0),
  unit_price  numeric(12, 2) not null check (unit_price >= 0),
  created_at  timestamptz not null default now()
);
create index idx_sale_lines_sale on sale_lines (sale_id);
create index idx_sale_lines_variant on sale_lines (variant_id);

-- Deferred FK: inventory_txns.sale_id -> sales.id.
alter table inventory_txns
  add constraint fk_inventory_txns_sale
  foreign key (sale_id) references sales (id);

-- Convenience view: current on-hand per variant (derived, never stored).
create view variant_stock as
select v.id as variant_id,
       coalesce(sum(t.qty), 0)::numeric as on_hand
from variants v
left join inventory_txns t on t.variant_id = v.id
group by v.id;

-- =============================================================================
-- 3. RLS + GRANTS
--   Single tenant: any authenticated shop user has full access. inventory_txns
--   is append-only (SELECT + INSERT only). RLS runs after the table privilege
--   check, so the GRANTs below are required (raw CREATE TABLE grants nothing to
--   the Supabase API roles).
-- =============================================================================
alter table categories      enable row level security;
alter table attribute_defs  enable row level security;
alter table products        enable row level security;
alter table variants        enable row level security;
alter table inventory_txns  enable row level security;
alter table sales           enable row level security;
alter table sale_lines      enable row level security;

do $$
declare
  tbl text;
  full_tables text[] := array['categories','attribute_defs','products','variants','sales','sale_lines'];
begin
  foreach tbl in array full_tables loop
    execute format(
      'create policy %I on %I for all to authenticated using (true) with check (true)',
      tbl || '_authenticated_all', tbl);
  end loop;
end;
$$;

-- Append-only ledger: SELECT + INSERT only.
create policy inventory_txns_authenticated_select
  on inventory_txns for select to authenticated using (true);
create policy inventory_txns_authenticated_insert
  on inventory_txns for insert to authenticated with check (true);

grant select, insert, update, delete on
  categories, attribute_defs, products, variants, sales, sale_lines
to authenticated;
grant select, insert on inventory_txns to authenticated;
grant select on variant_stock to authenticated;

-- Keep the ledger append-only even if a permissive policy slips in later.
revoke update, delete on inventory_txns from authenticated, anon;

-- =============================================================================
-- 4. RPCs
-- =============================================================================

-- receive_stock — post a positive receive txn for a variant. Returns txn id.
create or replace function receive_stock(
  p_variant_id uuid,
  p_qty        numeric,
  p_unit_cost  numeric,
  p_location   text,
  p_note       text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'Receive quantity must be positive';
  end if;
  if not exists (select 1 from variants where id = p_variant_id) then
    raise exception 'Unknown variant_id %', p_variant_id;
  end if;
  insert into inventory_txns (id, txn_type, variant_id, qty, unit_cost, location, note)
  values (v_id, 'receive', p_variant_id, p_qty, p_unit_cost, nullif(trim(p_location),''), nullif(trim(p_note),''));
  return v_id;
end;
$$;
grant execute on function receive_stock(uuid, numeric, numeric, text, text) to authenticated;

-- adjust_stock — post a signed adjustment (e.g. shrinkage, count correction).
create or replace function adjust_stock(
  p_variant_id uuid,
  p_qty        numeric,
  p_note       text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  if p_qty is null or p_qty = 0 then
    raise exception 'Adjustment quantity must be non-zero';
  end if;
  if not exists (select 1 from variants where id = p_variant_id) then
    raise exception 'Unknown variant_id %', p_variant_id;
  end if;
  insert into inventory_txns (id, txn_type, variant_id, qty, note)
  values (v_id, 'adjust', p_variant_id, p_qty, nullif(trim(p_note),''));
  return v_id;
end;
$$;
grant execute on function adjust_stock(uuid, numeric, text) to authenticated;

-- record_sale — atomic POS write: a sale header + its lines + one negative
-- 'sell' inventory_txn per line, all in one transaction (a function body runs in
-- a single implicit transaction). Input lines: [{variant_id, qty, unit_price}].
-- Returns the new sale id.
create or replace function record_sale(
  p_lines jsonb,
  p_note  text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id   uuid := gen_random_uuid();
  v_line      jsonb;
  v_variant   uuid;
  v_qty       integer;
  v_price     numeric;
  v_subtotal  numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;

  insert into sales (id, subtotal, note) values (v_sale_id, 0, nullif(trim(p_note),''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_variant := (v_line->>'variant_id')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_variant is null or not exists (select 1 from variants where id = v_variant) then
      raise exception 'Unknown variant_id % in sale line', v_variant;
    end if;
    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;

    insert into sale_lines (sale_id, variant_id, qty, unit_price)
    values (v_sale_id, v_variant, v_qty, v_price);

    -- Negative sell txn decrements on-hand.
    insert into inventory_txns (txn_type, variant_id, qty, sale_id)
    values ('sell', v_variant, -v_qty, v_sale_id);

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  update sales set subtotal = v_subtotal where id = v_sale_id;
  return v_sale_id;
end;
$$;
grant execute on function record_sale(jsonb, text) to authenticated;

-- =============================================================================
-- 5. SEED — tennis shop starter data
-- =============================================================================

-- Categories
insert into categories (name, sort_order) values
