-- >>> supabase/migrations/0009_stock_views.sql
-- =============================================================================
-- 0009_stock_views.sql — derived stock + low-stock views (AceStock)
--
-- On-hand is always derived from the append-only inventory_txns ledger, never
-- stored. These views expose it conveniently, plus a low-stock flag using the
-- effective reorder point (variant's own, falling back to the product's).
-- =============================================================================

-- Per-variant on-hand + low-stock flag.
create or replace view variant_stock_detail as
select
  v.id                                              as variant_id,
  v.product_id                                      as product_id,
  coalesce(sum(t.qty), 0)::numeric                  as on_hand,
  coalesce(v.reorder_point, p.reorder_point)        as reorder_point,
  (
    coalesce(v.reorder_point, p.reorder_point) is not null
    and coalesce(sum(t.qty), 0) <= coalesce(v.reorder_point, p.reorder_point)
  )                                                 as is_low
from variants v
join products p on p.id = v.product_id
left join inventory_txns t on t.variant_id = v.id
group by v.id, v.product_id, v.reorder_point, p.reorder_point;

-- Per-product roll-up: total on-hand, variant count, any low-stock variant.
create or replace view product_stock as
select
  p.id                                              as product_id,
  coalesce(sum(vsd.on_hand), 0)::numeric            as on_hand,
  count(v.id)                                       as variant_count,
  coalesce(bool_or(vsd.is_low), false)              as has_low_stock
from products p
left join variants v on v.product_id = p.id
left join variant_stock_detail vsd on vsd.variant_id = v.id
group by p.id;

grant select on variant_stock_detail to authenticated;
grant select on product_stock to authenticated;

-- >>> supabase/migrations/0010_variant_upc.sql
-- =============================================================================
-- 0010_variant_upc.sql — unique UPC per variant (AceStock)
--
-- A UPC (stored in variants.barcode) identifies a specific scannable item, so it
-- must be unique across all variants. This enables a scanned/typed UPC to resolve
-- to exactly one variant (groundwork for the home-screen search / scan-to-find
-- feature). Uniqueness is required at the app layer too (the add-variant form
-- requires a UPC); this index makes it a hard guarantee.
--
-- Partial index (where barcode is not null) so legacy variants without a UPC are
-- unaffected.
-- =============================================================================

create unique index if not exists uq_variants_barcode
  on variants (barcode)
  where barcode is not null;

-- >>> supabase/migrations/0011_fix_attribute_flags.sql
-- =============================================================================
-- 0011_fix_attribute_flags.sql — repair attribute_defs to the canonical set
--
-- Symptom this fixes: every variant shows "Default" and the add-item form shows
-- no dimension fields — because the live attribute_defs are missing the
-- is_variant_dimension flags (0008's seed used ON CONFLICT DO NOTHING, so if
-- rows already existed with wrong flags they were never corrected).
--
-- This re-asserts the canonical tennis attribute definitions with an UPSERT that
-- UPDATES existing rows (unlike the original DO NOTHING). Idempotent and safe to
-- run on a correct database (it's a no-op there).
--
-- NOTE: this overwrites attribute_defs to the standard set. If you've customized
-- attribute definitions by hand, review before running.
-- =============================================================================

insert into attribute_defs (category_id, name, value_type, unit, required, is_variant_dimension, enum_values, sort_order)
select c.id, a.name, a.value_type, a.unit, a.required, a.is_variant, a.enum_values, a.sort_order
from categories c
join (values
  -- Rackets
  ('Rackets','grip_size','enum',   null, true,  true,  '["4 1/8","4 1/4","4 3/8","4 1/2","4 5/8"]'::jsonb, 1),
  ('Rackets','head_size','number', 'in²',false, false, null::jsonb, 2),
  ('Rackets','weight',   'number', 'g',  false, false, null::jsonb, 3),
  ('Rackets','string_pattern','text', null, false, false, null::jsonb, 4),
  -- Strings
  ('Strings','gauge','enum', null, false, true,  '["15","15L","16","16L","17","18"]'::jsonb, 1),
  ('Strings','color','text', null, false, true,  null::jsonb, 2),
  ('Strings','material','text', null, false, false, null::jsonb, 3),
  ('Strings','length','number','ft', false, false, null::jsonb, 4),
  -- Grips
  ('Grips','type','enum', null, false, true, '["overgrip","replacement"]'::jsonb, 1),
  ('Grips','color','text', null, false, true, null::jsonb, 2),
  -- Balls
  ('Balls','type','enum', null, false, true, '["regular duty","extra duty","high altitude"]'::jsonb, 1),
  ('Balls','pack_size','number','count', false, true, null::jsonb, 2),
  -- Shoes
  ('Shoes','size','text', null, true, true, null::jsonb, 1),
  ('Shoes','width','enum', null, false, true, '["narrow","standard","wide"]'::jsonb, 2),
  ('Shoes','color','text', null, false, true, null::jsonb, 3),
  ('Shoes','gender','enum', null, false, false, '["men","women","junior","unisex"]'::jsonb, 4),
  -- Apparel
  ('Apparel','size','enum', null, true, true, '["XS","S","M","L","XL","XXL"]'::jsonb, 1),
  ('Apparel','color','text', null, false, true, null::jsonb, 2),
  ('Apparel','gender','enum', null, false, false, '["men","women","junior","unisex"]'::jsonb, 3),
  -- Bags
  ('Bags','capacity','text', null, false, true, null::jsonb, 1),
  ('Bags','color','text', null, false, true, null::jsonb, 2),
  -- Accessories
  ('Accessories','type','text', null, false, false, null::jsonb, 1)
) as a(cat, name, value_type, unit, required, is_variant, enum_values, sort_order)
  on a.cat = c.name
on conflict (category_id, name) do update
  set value_type           = excluded.value_type,
      unit                 = excluded.unit,
      required             = excluded.required,
      is_variant_dimension = excluded.is_variant_dimension,
      enum_values          = excluded.enum_values,
      sort_order           = excluded.sort_order;

-- >>> supabase/migrations/0012_customers.sql
-- =============================================================================
-- 0012_customers.sql — customers + link sales to a customer (AceStock)
--
-- Lets a sale be recorded under a customer and builds purchase history
-- (customer → sales → sale_lines → variants → products). Walk-in sales leave
-- customer_id null.
--
-- Re-runnable: drops and recreates the customers table + sales.customer_id, so
-- applying it again is safe (any existing customer_id links are reset).
-- =============================================================================

-- Idempotent reset (safe to re-run; removes the column's FK dependency first).
alter table sales drop column if exists customer_id;
drop table if exists customers cascade;

create table customers (
  id            uuid primary key default gen_random_uuid(),
  first_name    text not null,
  last_name     text not null,
  phone_number  text,
  email         text,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index idx_customers_last_first on customers (lower(last_name), lower(first_name));

create trigger trg_customers_updated_at
  before update on customers
  for each row execute function set_updated_at();

-- Link sales to an optional customer.
alter table sales
  add column customer_id uuid references customers (id);
create index idx_sales_customer on sales (customer_id);

-- -----------------------------------------------------------------------------
-- RLS + grants
-- -----------------------------------------------------------------------------
alter table customers enable row level security;
create policy customers_authenticated_all
  on customers for all to authenticated using (true) with check (true);
grant select, insert, update, delete on customers to authenticated;

-- -----------------------------------------------------------------------------
-- record_sale — accepts an optional customer_id. Atomic: sale header (+ customer)
-- + lines + one sell inventory_txn per line.
-- -----------------------------------------------------------------------------
drop function if exists record_sale(jsonb, text);
drop function if exists record_sale(jsonb, uuid, text);

create or replace function record_sale(
  p_lines       jsonb,
  p_customer_id uuid,
  p_note        text
)
returns uuid
language plpgsql
security invoker
as $$
declare
  v_sale_id   uuid := gen_random_uuid();
  v_line      jsonb;
  v_variant   uuid;
  v_qty       integer;
  v_price     numeric;
  v_subtotal  numeric := 0;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'A sale needs at least one line';
  end if;
  if p_customer_id is not null
     and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'Unknown customer_id %', p_customer_id;
  end if;

  insert into sales (id, customer_id, subtotal, note)
  values (v_sale_id, p_customer_id, 0, nullif(trim(p_note), ''));

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_variant := (v_line->>'variant_id')::uuid;
    v_qty     := (v_line->>'qty')::integer;
    v_price   := (v_line->>'unit_price')::numeric;

    if v_variant is null or not exists (select 1 from variants where id = v_variant) then
      raise exception 'Unknown variant_id % in sale line', v_variant;
    end if;
    if v_qty is null or v_qty <= 0 then
      raise exception 'Sale line quantity must be positive';
    end if;
    if v_price is null or v_price < 0 then
      raise exception 'Sale line price must be >= 0';
    end if;

    insert into sale_lines (sale_id, variant_id, qty, unit_price)
    values (v_sale_id, v_variant, v_qty, v_price);

    insert into inventory_txns (txn_type, variant_id, qty, sale_id)
    values ('sell', v_variant, -v_qty, v_sale_id);

    v_subtotal := v_subtotal + (v_qty * v_price);
  end loop;

  update sales set subtotal = v_subtotal where id = v_sale_id;
  return v_sale_id;
end;
$$;

grant execute on function record_sale(jsonb, uuid, text) to authenticated;

-- >>> supabase/migrations/0013_customer_rackets.sql
